from typing import List

class Solution:
    def numSubmat(self, mat: List[List[int]]) -> int:
        cols = len(mat[0])
        heights = [0] * cols
        ans = 0

        for row in mat:
            for j, value in enumerate(row):
                heights[j] = heights[j] + 1 if value == 1 else 0

            stack = []
            subtotal = 0
            for i, height in enumerate(heights):
                while stack and heights[stack[-1]] >= height:
                    p = stack.pop()
                    left = stack[-1] if stack else -1
                    subtotal -= (heights[p] - height) * (p - left)
                stack.append(i)
                subtotal += height
                ans += subtotal

        return ans

