import java.io.*;
import java.util.*;

class Solution {
    public int numSubmat(int[][] mat) {
        int cols = mat[0].length;
        int[] heights = new int[cols];
        int answer = 0;

        for (int[] row : mat) {
            for (int j = 0; j < cols; j++) {
                heights[j] = row[j] == 1 ? heights[j] + 1 : 0;
            }

            int[] stack = new int[cols];
            int top = -1;
            int subtotal = 0;
            for (int i = 0; i < cols; i++) {
                while (top >= 0 && heights[stack[top]] >= heights[i]) {
                    int p = stack[top--];
                    int left = top >= 0 ? stack[top] : -1;
                    subtotal -= (heights[p] - heights[i]) * (p - left);
                }
                stack[++top] = i;
                subtotal += heights[i];
                answer += subtotal;
            }
        }
        return answer;
    }
}

